   274|async function requestIVXAIAnswer(input: {
   275|  message: string;
   276|  history: PublicChatHistoryItem[];
   277|  sessionId: string;
   278|  businessContext: string | null;
   279|  images: PublicChatImageAttachment[];
   280|  documents: DealDocumentAttachment[];
   281|  extractedDocuments: ExtractedDocument[];
   282|  videoUnderstandings: VideoUnderstanding[];
   283|}): Promise<PublicChatAnswerResult> {
   284|  const endpoint = getGatewayModelEndpoint();
   285|  if (!isPublicChatAIConfigured() || !endpoint) {
   286|    throw new Error('IVX AI proxy configuration is missing.');
   287|  }
   288|
   289|  const promptParts = [
   290|    'Recent public chat transcript:',
   291|    buildTranscript(input.history),
   292|    '',
   293|  ];
   294|  if (input.businessContext) {
   295|    promptParts.push(input.businessContext, '');
   296|  }
   297|  if (input.images.length > 0) {
   298|    promptParts.push(
   299|      `Note: ${input.images.length} image attachment(s) accompany this message — analyze them as part of your answer.`,
   300|      '',
   301|    );
   302|  }
   303|  if (input.documents.length > 0) {
   304|    promptParts.push(
   305|      `Note: ${input.documents.length} deal-room document(s) accompany this message: ${input.documents
   306|        .map((doc) => `${doc.name ?? doc.url} [${doc.kind}] ${doc.url}`)
   307|        .join('; ')}. Analyze them as an acquisition analyst per the instructions above.`,
   308|      '',
   309|    );
   310|  }
   311|  const extractedContentBlock = buildExtractedDocumentContentBlock(input.extractedDocuments);
   312|  if (extractedContentBlock) {
   313|    promptParts.push(extractedContentBlock, '');
   314|  }
   315|  const videoContentBlock = buildVideoUnderstandingBlock(input.videoUnderstandings);
   316|  if (videoContentBlock) {
   317|    promptParts.push(videoContentBlock, '');
   318|  }
   319|  promptParts.push(
   320|    `User message: ${input.message || (input.images.length > 0 ? 'Analyze the attached image(s).' : '')}`,
   321|    '',
   322|    'Reply directly to the user message. If the user asks for an exact token or proof string, include it exactly.',
   323|  );
   324|
   325|  const result = await requestIVXAIText({
   326|    module: 'public-chat',
   327|    requestId: input.sessionId,
   328|    model: getPublicChatModel(),
   329|    system: buildSystemPrompt(
   330|      input.sessionId,
   331|      input.images.length > 0,
   332|      input.documents,
   333|      extractedContentBlock,
   334|      videoContentBlock,
   335|    ),
   336|    prompt: promptParts.join('\n'),
   337|    images: input.images.length > 0 ? input.images : undefined,
   338|  });
   339|
   340|  return {
   341|    answer: result.text,
   342|    model: result.providerMetadata.model,
   343|    source: 'chatgpt',
   344|    endpoint: result.providerMetadata.endpoint,
   345|    imageCount: input.images.length,
   346|    providerMetadata: result.providerMetadata,
   347|  };
   348|}
