input.command:
cat qa/p17-transcript.json | bun -e '
const d = JSON.parse(await Bun.stdin.text());
const results = d.results;

// Check for banned phrase
const bannedPhrase = "To give you the most useful answer, I need to understand";
const withBanned = results.filter(r => r.answer.includes(bannedPhrase));
console.log("Responses with banned phrase:", withBanned.length, "/", results.length);

// Check followup sufficient_info: do they answer directly?
const sufficient = results.filter(r => r.category === "followup" && r.type === "sufficient_info");
console.log("\nSufficient-info followup questions:", sufficient.length);
for (const r of sufficient) {
  const firstLine = r.answer.split("\n")[0].slice(0, 100);
  const startsWithQuestion = r.answer.match(/^(To give you|I need to understand|Before I|Let me ask)/i);
  console.log(`  ${r.id}: ${startsWithQuestion ? "OVER-CLARIFIES" : "DIRECT"} — ${firstLine}`);
}

// Check followup needs_clarification: do they ask questions?
const needsClar = results.filter(r => r.category === "followup" && r.type === "needs_clarification");
console.log("\nNeeds-clarification followup questions:", needsClar.length);
for (const r of needsClar) {
  const hasQuestion = r.answer.includes("?") || r.answer.match(/\d+\.\s+\*\*/);
  const firstLine = r.answer.split("\n")[0].slice(0, 100);
  console.log(`  ${r.id}: ${hasQuestion ? "ASKS QUESTIONS" : "NO QUESTIONS"} — ${firstLine}`);
}

// Check root-cause structure
const dev = results.filter(r => r.category === "dev_rootcause");
let rootCauseStructure = 0;
for (const r of dev) {
  if (r.answer.match(/SYMPTOM|MOST LIKELY CAUSE|diagnostic/i)) rootCauseStructure++;
}
console.log("\nDev/root-cause with diagnostic chain structure:", rootCauseStructure, "/", dev.length);

// Check multi-turn correction handling
const mt05 = results.filter(r => r.id.startsWith("P17-MT-05"));
console.log("\nMT-05 correction handling:");
for (const r of mt05) {
  console.log(`  ${r.id}: ${r.answer.slice(0, 150)}`);
}

// Provenance
const allOk = results.every(r => r.ok);
const allReal = results.every(r => r.source === "vercel_ai_gateway" && r.model === "openai/gpt-4o");
const uniqueGenIds = new Set(results.map(r => r.generationId)).size;
const all200 = results.every(r => r.status === 200);
console.log("\n=== PROVENANCE ===");
console.log("All status 200:", all200);
console.log("All OK:", allOk);
console.log("All real gateway:", allReal);
console.log("Unique generationIds:", uniqueGenIds, "/", results.length);
console.log("Avg latency:", Math.round(results.reduce((s,r)=>s+r.latency,0)/results.length), "ms");
console.log("Min latency:", Math.min(...results.map(r=>r.latency)), "ms");
console.log("Max latency:", Math.max(...results.map(r=>r.latency)), "ms");
console.log("Total responses:", results.length);
'

